<!doctype html>
<html lang="en">
<head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Submission history · UIU Recruitment Portal</title>
<style>body{margin:0;background:#f6f8fb;color:#0b1f3a;font-family:Inter,ui-sans-serif,system-ui,-apple-system,"Segoe UI",sans-serif}.page{max-width:980px;margin:0 auto;padding:42px 22px}.top{display:flex;justify-content:space-between;align-items:center;gap:18px;margin-bottom:26px}.top h1{margin:0;font-size:30px}.top a{color:#1769aa;font-weight:700;text-decoration:none}.card{background:#fff;border:1px solid #d7dee8;border-radius:12px;overflow:auto}.card table{width:100%;border-collapse:collapse;min-width:650px}.card th,.card td{text-align:left;padding:15px;border-bottom:1px solid #edf0f4}.card th{font-size:12px;text-transform:uppercase;color:#69778d}.card tr:last-child td{border-bottom:0}.muted{color:#69778d;font-size:13px}.badge{display:inline-block;padding:4px 8px;background:#eaf8ef;color:#187345;border-radius:999px;font-size:11px;font-weight:700}</style>
</head>
<body><main class="page"><div class="top"><div><h1>Submission history</h1><div class="muted">Your submitted assessment versions</div></div><a href="<?= site_url('exam/dashboard') ?>">← Back to dashboard</a></div><?php if (!$history): ?><div class="card" style="padding:22px;color:#69778d">No submissions yet.</div><?php else: ?><div class="card"><table><thead><tr><th>Exam</th><th>Version</th><th>Action</th><th>Reference</th><th>Submitted at</th></tr></thead><tbody><?php foreach ($history as $entry): ?><tr><td><?= esc($entry['exam_title'] ?: 'Assessment') ?></td><td><?= (int) $entry['application_version'] ?></td><td><span class="badge"><?= esc($entry['action'] === 'RESUBMIT' ? 'Resubmitted' : 'Submitted') ?></span></td><td><?= esc($entry['application_reference']) ?></td><td><?= esc($entry['submitted_at']) ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></main></body></html>
